                    cols.append(h.lower())
            except Exception: pass
        if 'gray' in txt or 'grey' in txt: cols.append('gray')
    if not cols: return None
    dom=max(set(cols),key=cols.count)
    return dom if cols.count(dom)>=3 else None

def norm(x):
    t=re.sub(r'\s+',' ',str(x or '').strip().lower())
    if not t: return None
    if t in ('s','sen','sensitive'): return 1
    if t in ('r','res','resistant'): return 0
    if re.search(r'(no response|non[- ]?responder|resist|ineffective|progress|disease progression)',t): return 0
    if re.search(r'(sensitive|responder|responded|partial response|complete response|\bpr\b|\bcr\b|effective)',t): return 1
    return None

cands=[]
for r in range(hdr_i+1,len(rows)):
    idv=str(rows[r][id_col] or '').strip()
    if not re.search(r'LC\d+',idv): continue
    if gray_color(r) is not None:
        cands.append(r)
if len(cands)!=10:
    cands=[]
    for r in range(hdr_i+1,len(rows)):
        idv=str(rows[r][id_col] or '').strip()
        if re.search(r'LC\d+',idv) and truth_col is not None and score_col is not None and norm(rows[r][truth_col]) is not None and norm(rows[r][score_col]) is not None:
            cands.append(r)

records=[]; ok=len(cands)==10 and truth_col is not None and score_col is not None
for r in cands:
