      'threshold_timing':{'value':'not_applicable','evidence':['article:p27'],'explanation':'No numeric binary cutoff is reported for the categorical clinical-concordance endpoint.'},
      'patient_mapping':{'value':'individual_available','evidence':id_refs,'explanation':'Supplementary Data 2 identifies the individual organoid/patient lines used in the comparison.'},
      'regimen_match':{'value':'matched','evidence':['article:p27'],'explanation':'Only lines whose administered clinical drugs were also tested on-chip were included.'},
      'n_units':{'value':10,'evidence':id_refs,'explanation':'Ten evaluable organoid lines had comparable administered regimens and clinical response assessments.'},
      'split':{'value':'none','evidence':['article:p27'],'explanation':'The report describes direct paired assay-clinical comparison, not a trained classifier or held-out model split.'}
    },'headline':{'metric':'accuracy','reported':1.0,'reported_evidence':['article:p27'],'threshold':None,'op':'==','score_direction':'higher','records':records},'notes':['The article states 100% accuracy and specificity in ten evaluable lines; the other 11 of 21 lines were not comparable or not evaluable.']}
else:
