      'direction':{'value':'lower_sensitive','evidence':['article:p16'],'explanation':'Lower viability indicates sensitivity.'},
      'threshold_rule':{'value':'categorical','evidence':['article:p27'],'explanation':'Categorical response calls expected.'},
